-- Hand-written hopon originals, seeded as ordinary published games.
INSERT INTO games(owner, title, description, html, published, author) VALUES('hopon','Toast Panic','Wait… wait… CATCH! Save your breakfast in a five-second reaction challenge.',replace('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Toast Panic</title><style>*{box-sizing:border-box}body{margin:0;font-family:system-ui,sans-serif;background:var(--bg);color:#18151b;overflow:hidden}main{height:100dvh;display:flex;flex-direction:column;align-items:center;justify-content:space-between;padding:24px 20px;gap:12px;text-align:center;background-image:radial-gradient(#0001 2px,transparent 2px);background-size:22px 22px}header{width:100%;display:flex;justify-content:space-between;font-size:11px;font-weight:900;letter-spacing:1px}h1{font-size:clamp(32px,9vw,56px);line-height:.95;margin:0;font-weight:1000;letter-spacing:-2px;text-transform:uppercase}p{margin:0;font-size:13px;font-weight:600}button{font:inherit;cursor:pointer;touch-action:manipulation;color:inherit}button:focus-visible{outline:4px solid #282071;outline-offset:4px}#action{border:3px solid #18151b;border-radius:14px;background:white;box-shadow:0 5px 0 #18151b;min-height:52px;min-width:180px;padding:12px 24px;font-weight:900;font-size:18px}#action:active{transform:translateY(4px);box-shadow:0 1px 0 #18151b}.stage{flex:1;min-height:100px;width:100%;position:relative;display:flex;align-items:center;justify-content:center}#message{min-height:35px;font-weight:800}progress{width:100%;height:12px;accent-color:#18151b}footer{font-size:10px;font-weight:800;letter-spacing:1px}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}body{--bg:#ffc54d}.toaster{width:180px;height:115px;background:#ff624c;border:5px solid #18151b;border-radius:26px 26px 15px 15px;position:relative;box-shadow:9px 9px 0 #18151b}.toaster:before{content:'''';position:absolute;left:18px;right:18px;top:-13px;height:19px;background:#18151b;border-radius:50%}.toaster span{display:block;margin-top:45px;font-size:25px;font-weight:1000;transform:rotate(-8deg)}#toast{position:absolute;font-size:95px;top:50%;transform:translateY(-40%);transition:transform .12s;line-height:1}body.popped #toast{transform:translateY(-160%) rotate(-12deg)}</style></head><body><main><header><span>REACTION · 5 SEC</span></header><h1 id="command">Catch it!</h1><p>Wait for the toast. Then hit CATCH!</p><div class="stage"><div id="toast" aria-hidden="true">🍞</div><div class="toaster" aria-hidden="true"><span>HOT!</span></div></div><p id="message" role="status" aria-live="polite">Breakfast waits for nobody.</p><progress id="timer" value="5" max="5" aria-label="Time remaining"></progress><button id="action">Start</button><footer>CLICK / TAP / SPACE</footer></main><script>const action=document.querySelector(''#action''),message=document.querySelector(''#message''),command=document.querySelector(''#command''),timer=document.querySelector(''#timer'');\nlet state=''idle'',started=0,popAt=0,loop;\nfunction finish(win,text){state=''done'';clearInterval(loop);command.textContent=win?''Nice catch!'':''Too slow!'';message.textContent=text;action.textContent=''Again'';}\nfunction tick(){const elapsed=performance.now()-started;timer.value=Math.max(0,5-elapsed/1000);if(state===''waiting''&&elapsed>=popAt){state=''popped'';document.body.classList.add(''popped'');command.textContent=''CATCH!'';message.textContent=''NOW!'';}if(state===''popped''&&elapsed>=popAt+850)finish(false,''The toast escaped. Try again!'');}\nfunction act(){if(state===''idle''||state===''done''){clearInterval(loop);document.body.classList.remove(''popped'');state=''waiting'';started=performance.now();popAt=1500+Math.random()*1800;timer.value=5;command.textContent=''Wait…'';message.textContent=''Don’t catch too early!'';action.textContent=''CATCH!'';loop=setInterval(tick,16);return;}tick();if(state===''popped''){finish(true,''Breakfast saved. Perfect timing!'');}else if(state===''waiting''){finish(false,''Too early! Wait until the toast pops.'');command.textContent=''Too early!'';}}\naction.addEventListener(''click'',act);document.addEventListener(''keydown'',e=>{if(e.code===''Space''&&e.target!==action){e.preventDefault();if(!e.repeat)act();}});\n</script></body></html>','\n',char(10)),1,'hopon');
--> statement-breakpoint
INSERT INTO games(owner, title, description, html, published, author) VALUES('hopon','Odd Duck','Spot the sunglasses duck three times in six seconds. One wrong pick and you’re toast.',replace('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Odd Duck</title><style>*{box-sizing:border-box}body{margin:0;font-family:system-ui,sans-serif;background:var(--bg);color:#18151b;overflow:hidden}main{height:100dvh;display:flex;flex-direction:column;align-items:center;justify-content:space-between;padding:24px 20px;gap:12px;text-align:center;background-image:radial-gradient(#0001 2px,transparent 2px);background-size:22px 22px}header{width:100%;display:flex;justify-content:space-between;font-size:11px;font-weight:900;letter-spacing:1px}h1{font-size:clamp(32px,9vw,56px);line-height:.95;margin:0;font-weight:1000;letter-spacing:-2px;text-transform:uppercase}p{margin:0;font-size:13px;font-weight:600}button{font:inherit;cursor:pointer;touch-action:manipulation;color:inherit}button:focus-visible{outline:4px solid #282071;outline-offset:4px}#action{border:3px solid #18151b;border-radius:14px;background:white;box-shadow:0 5px 0 #18151b;min-height:52px;min-width:180px;padding:12px 24px;font-weight:900;font-size:18px}#action:active{transform:translateY(4px);box-shadow:0 1px 0 #18151b}.stage{flex:1;min-height:100px;width:100%;position:relative;display:flex;align-items:center;justify-content:center}#message{min-height:35px;font-weight:800}progress{width:100%;height:12px;accent-color:#18151b}footer{font-size:10px;font-weight:800;letter-spacing:1px}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}body{--bg:#9c8cff}#flock{width:min(100%,340px);display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.duck{border:3px solid #18151b;border-radius:18px;background:#ffe36e;aspect-ratio:1;box-shadow:4px 4px 0 #18151b;position:relative;font-size:clamp(34px,10vw,62px);padding:0;min-height:58px}.duck:disabled{cursor:default}.duck small{position:absolute;left:6px;top:3px;font-size:11px}.glasses{position:absolute;inset:0;display:grid;place-items:center;font-size:35px;transform:translate(6px,-7px)}</style></head><body><main><header><span>SPOT IT · 6 SEC</span></header><h1 id="command">Odd duck!</h1><p>Pick the duck wearing sunglasses. Three times!</p><div class="stage"><div id="flock" aria-label="Duck choices"></div></div><p id="message" role="status" aria-live="polite">One duck is acting suspicious.</p><progress id="timer" value="6" max="6" aria-label="Time remaining"></progress><button id="action">Start</button><footer>TAP A DUCK / KEYS 1–6</footer></main><script>const action=document.querySelector(''#action''),message=document.querySelector(''#message''),command=document.querySelector(''#command''),timer=document.querySelector(''#timer''),flock=document.querySelector(''#flock'');\nlet state=''idle'',score=0,odd=0,started=0,loop;\nfunction draw(){flock.replaceChildren();for(let i=0;i<6;i++){const button=document.createElement(''button'');button.className=''duck'';button.disabled=state!==''playing'';button.setAttribute(''aria-label'',''Duck ''+(i+1)+(i===odd?'' wearing sunglasses'':''''));button.innerHTML=''<small>''+(i+1)+''</small><span aria-hidden="true">🦆</span>''+(i===odd?''<span class="glasses" aria-hidden="true">🕶️</span>'':'''');button.addEventListener(''click'',()=>pick(i));flock.append(button);}}\nfunction finish(win,text){state=''done'';clearInterval(loop);command.textContent=win?''Spotted!'':''Oh, duck!'';message.textContent=text;action.hidden=false;action.textContent=''Again'';draw();}\nfunction pick(index){if(state!==''playing'')return;if(performance.now()-started>=6000){finish(false,''Time’s up. Give it another go!'');return;}if(index!==odd){finish(false,''That duck was innocent!'');return;}score++;if(score===3){finish(true,''3 out of 3. Nothing gets past you!'');return;}message.textContent=score+'' / 3 — find the next one!'';odd=(odd+1+Math.floor(Math.random()*5))%6;draw();}\naction.addEventListener(''click'',()=>{clearInterval(loop);state=''playing'';score=0;started=performance.now();odd=Math.floor(Math.random()*6);timer.value=6;command.textContent=''Find it!'';message.textContent=''0 / 3 — the sunglasses duck!'';action.hidden=true;draw();loop=setInterval(()=>{timer.value=Math.max(0,6-(performance.now()-started)/1000);if(performance.now()-started>=6000)finish(false,''Time’s up. Give it another go!'');},16);});\ndocument.addEventListener(''keydown'',e=>{if(/^[1-6]$/.test(e.key)&&!e.repeat)pick(Number(e.key)-1);});draw();\n</script></body></html>','\n',char(10)),1,'hopon');
